export const ALL_PEQ_PRESETS: PeqPreset[] = [...AUTOEQ_PRESETS, ...CREATIVE_PRESETS];

export function presetToProfile(p: PeqPreset, enabled: boolean): HostEqProfile {
  return { name: p.name, enabled, preamp: p.preamp, autoPreamp: false, bands: p.bands.map((b) => ({ ...b })) };
}

export function recommendedFor(modelCode: string | undefined): PeqPreset | undefined {
  if (!modelCode) return undefined;
  return ALL_PEQ_PRESETS.find((p) => p.models.includes(modelCode));
}
